Y2B_RUN_ID=preview
RES_FILE=/var/tmp/runcommand/result.res
LOG_FILE=/var/tmp/runcommand/result.log
mkdir -p "$(dirname "$RES_FILE")" "$(dirname "$LOG_FILE")"
: > "$RES_FILE"
printf '__Y2B_RUN__=%s\n' "$(printf '%s' "$Y2B_RUN_ID" | base64 -w0)" >> "$RES_FILE"
echo "===== $(date -Is) run start (job sha256 85831c0c51cc5cfa7aaeaef57ca7f5097356485dc1f1f1a4560e25ba5bfaa40b)" >> "$LOG_FILE"

write_result() {          # $1=NAME $2=VALUE
  if [ "$#" -ne 2 ] || [[ ! "$1" =~ ^[A-Z_][A-Z0-9_]*$ ]] || [[ "$1" == __Y2B_* ]]; then
    echo "write_result: expected 'write_result NAME VALUE' with NAME matching ^[A-Z_][A-Z0-9_]*\$ (step $Y2B_STEP_NAME)" >> "$LOG_FILE"
    return 1
  fi
  printf '%s=%s\n' "$1" "$(printf '%s' "$2" | base64 -w0)" >> "$RES_FILE"
  printf '%s="%s"\n' "$1" "$2" >> "$LOG_FILE"
}
export -f write_result; export RES_FILE LOG_FILE

y2b_step_1() {            # check-hip-version
  # Query package or version
  VERSION=$(rpm -q --queryformat '%{VERSION}' hip 2>/dev/null || echo "NOT_INSTALLED")
  write_result HIP_VERSION "$VERSION"
}
y2b_step_2() {            # check-kernel-count
  COUNT=$(dnf repoquery --installed kernel 2>/dev/null | wc -l)
  write_result KERNEL_COUNT "$COUNT"
}
y2b_step_3() {            # complex-hardware-audit  (from audit_hardware.sh)
  # Hardware audit simulation
  if grep -q "flags.*sse" /proc/cpuinfo 2>/dev/null || [ -e /proc/cpuinfo ]; then
    write_result HW_AUDIT_STATUS "PASS"
  else
    write_result HW_AUDIT_STATUS "FAIL"
  fi
}
export -f y2b_step_1 y2b_step_2 y2b_step_3

run_step() {              # $1=function $2=timeout $3=step index $4=step name
  export Y2B_STEP_NAME="$4"
  echo "=== $(date -Is) step $3 $4" >> "$LOG_FILE"
  timeout "$2" bash -c "$1" >> "$LOG_FILE" 2>&1
  local rc=$? status=ok
  if [ "$rc" -eq 124 ]; then status=timeout; elif [ "$rc" -ne 0 ]; then status="rc=$rc"; fi
  printf '__Y2B_STEP_%s__=%s\n' "$3" "$(printf '%s' "$status" | base64 -w0)" >> "$RES_FILE"
}
run_step y2b_step_1 120 1 check-hip-version
run_step y2b_step_2 120 2 check-kernel-count
run_step y2b_step_3 120 3 complex-hardware-audit

printf '__Y2B_DONE__=%s\n' "$(printf '%s' "$Y2B_RUN_ID" | base64 -w0)" >> "$RES_FILE"
exit 0
